  "indices_and_sets": {
    "I": "Set of SKUs (products), i = 1 to 80"
  },
  "parameters": {
    "Sale_Price_Per_Unit_i": "Revenue per unit for SKU i (from column Sale_Price_Per_Unit)",
    "Material_Cost_Per_Unit_i": "Material cost per unit for SKU i (from column Material_Cost_Per_Unit)",
    "Molding_Mins_Req_i": "Molding minutes required per unit for SKU i (from column Molding_Mins_Req)",
    "Assembly_Mins_Req_i": "Assembly minutes required per unit for SKU i (from column Assembly_Mins_Req)",
    "Max_Market_Capacity_i": "Maximum market demand for SKU i (from column Max_Market_Capacity)",
    "Available_Molding_Capacity": "Total available molding minutes per planning period (MISSING - see handling notes)",
    "Available_Assembly_Capacity": "Total available assembly minutes per planning period (MISSING - see handling notes)"
  },
  "decision_variables": {
    "x_i": "Production quantity for SKU i, where x_i ∈ ℤ_{≥0}"
  },
  "objective_function": {
    "description": "Maximize total profit across all SKUs",
    "equation": "Maximize Z = Σ_{i ∈ I} (Sale_Price_Per_Unit_i - Material_Cost_Per_Unit_i) * x_i"
  },
  "constraints": [
    {
      "name": "Molding Capacity Constraint",
      "equation": "Σ_{i ∈ I} Molding_Mins_Req_i * x_i ≤ Available_Molding_Capacity"
    },
    {
      "name": "Assembly Capacity Constraint",
      "equation": "Σ_{i ∈ I} Assembly_Mins_Req_i * x_i ≤ Available_Assembly_Capacity"
    },
    {
      "name": "Demand Limit Constraint",
      "equation": "x_i ≤ Max_Market_Capacity_i  ∀ i ∈ I"
    },
    {
      "name": "Integrality & Non-negativity",
      "equation": "x_i ∈ ℤ_{≥0}  ∀ i ∈ I"
    }
  ],
  "parameter_assumptions_and_missing_data_handling": {
    "note": "The dataset does not contain total available capacity limits for molding or assembly. These must be introduced as tunable planning parameters external to the CSV.",
    "recommended_approaches": [
      "Baseline/Unconstrained Analysis: Set Available_Molding_Capacity and Available_Assembly_Capacity to a sufficiently large value (e.g., Σ Molding_Mins_Req_i * Max_Market_Capacity_i) to identify the theoretical profit maximum without resource bottlenecks.",
      "Historical Derivation: Use Previous_Quarter_Sales data to calculate total minutes consumed historically, then divide by a target utilization rate (e.g., 0.85) to estimate realistic capacity.",
      "Operational Planning Input: Derive from shift schedules: (Shift_Hours * 60 * Number_of_Machines * Working_Days). This should be provided by the operations team as a tunable input to the model."
    ]
  }
}
```

